import abc
import re

# Keys are generated by the API, so a strict format costs nothing: slash-separated segments of
# letters, digits, "_", "-" and ".", none starting with "." (so no "..", hidden files or absolute paths)
_KEY_PATTERN = re.compile(r"[A-Za-z0-9_-][A-Za-z0-9._-]*(/[A-Za-z0-9_-][A-Za-z0-9._-]*)*")


def validate_key(key: str) -> str:
    """Return the key unchanged, or raise ValueError if it isn't a safe relative path.

    Every FileStorage calls this, so a key is accepted or rejected the same way on every provider.
    """
    if not _KEY_PATTERN.fullmatch(key):
        raise ValueError(f"Invalid storage key {key!r}: use slash-separated letters, digits, '_', '-' and '.'")
    return key


class FileStorage(abc.ABC):
    """Abstract base class for storing uploaded receipt files (local disk, S3, Blob Storage)."""

    @abc.abstractmethod
    def upload(self, key: str, content: bytes) -> str:
        """Store a file, replacing any file already stored under the same key.

        Args:
            key: Relative path-like name, e.g. 'receipts/3f2a.pdf'.
            content: Raw file bytes.

        Returns:
            str: The key to pass to download().

        Raises:
            ValueError: If the key fails validate_key().
        """
        pass

    @abc.abstractmethod
    def download(self, key: str) -> bytes:
        """Read a stored file.

        Args:
            key: A key returned by upload().

        Returns:
            bytes: The file content.

        Raises:
            FileNotFoundError: If no file is stored under the key.
            ValueError: If the key fails validate_key().
        """
        pass
